    ("partial-array-trailing", """import jiter\nraw = b'[\"a\", true, null, 1, \"unfinished'\nassert jiter.from_json(raw, partial_mode='trailing-strings') == ['a', True, None, 1, 'unfinished']\nresult = True"""),
    ("partial-object", """import jiter\nassert jiter.from_json(b'{\"a\": 1, \"b\": 2, \"c', partial_mode=True) == {'a': 1, 'b': 2}\nresult = True"""),
    ("partial-object-trailing", """import jiter\nassert jiter.from_json(b'{\"a\": 1, \"b\": \"part', partial_mode='trailing-strings') == {'a': 1, 'b': 'part'}\nresult = True"""),
    ("partial-utf8", """import jiter\nassert jiter.from_json(b'\"abc\\xe2\\x82', partial_mode='trailing-strings') == 'abc'\nresult = True"""),
    ("error-eof", """import jiter\ntry: jiter.from_json(b'[1')\nexcept ValueError: result = True\nelse: result = False"""),
    ("error-invalid", """import jiter\ntry: jiter.from_json(b'xx')\nexcept ValueError: result = True\nelse: result = False"""),
    ("error-trailing", """import jiter\ntry: jiter.from_json(b'1 2')\nexcept ValueError: result = True\nelse: result = False"""),
    ("error-duplicate", """import jiter\ntry: jiter.from_json(b'{\"x\": 1, \"x\": 2}', catch_duplicate_keys=True)\nexcept ValueError as exc: assert 'duplicate' in str(exc).lower(); result = True\nelse: result = False"""),
    ("error-invalid-mode", """import jiter\ntry: jiter.from_json(b'1', float_mode='bad')\nexcept (ValueError, TypeError): result = True\nelse: result = False"""),
    ("string-unicode", """import jiter\nassert jiter.from_json('{\"中文\": \"€\"}'.encode()) == {'中文': '€'}\nresult = True"""),
    ("string-escapes", """import jiter\nvalue = jiter.from_json(b'\"a\\\\n\\\\t\\\\\\\\\\\\\"b\"')\nassert value == 'a' + chr(10) + chr(9) + chr(92) + chr(34) + 'b'\nresult = True"""),
    ("string-surrogate", """import jiter\nassert jiter.from_json(b'\"\\ud83d\\udca9\"') == '💩'\nresult = True"""),
    ("nested-values", """import jiter\nassert jiter.from_json(b'{\"a\": [{\"b\": [1, 2, 3]}]}') == {'a': [{'b': [1, 2, 3]}]}\nresult = True"""),
    ("cache-all", """import jiter\njiter.cache_clear(); jiter.from_json(b'{\"foo\": \"bar\", \"spam\": 3}', cache_mode='all')\nassert jiter.cache_usage() == 3\nresult = True"""),
    ("cache-keys", """import jiter\njiter.cache_clear(); jiter.from_json(b'{\"foo\": \"bar\", \"spam\": 3}', cache_mode='keys')\nassert jiter.cache_usage() == 2\nresult = True"""),
    ("cache-none", """import jiter\njiter.cache_clear(); jiter.from_json(b'{\"foo\": \"bar\", \"spam\": 3}', cache_mode='none')\nassert jiter.cache_usage() == 0\nresult = True"""),
