    ("lossless-convert", """from decimal import Decimal\nimport jiter\nf = jiter.LosslessFloat(b'123.45')\nassert float(f) == 123.45 and f.as_decimal() == Decimal('123.45')\nresult = True"""),
    ("lossless-scientific", """import jiter\nf = jiter.LosslessFloat(b'1.23e4')\nassert float(f) == 12300 and str(f) == '1.23e4'\nresult = True"""),
